下面是一個使用氣泡排序演算法的簡單示例，你可以按照自己的需要修改它。

```c++
#include<iostream>
using namespace std;

// 氣泡排序函式，引數為陣列指標和陣列長度
void bubbleSort(int *arr, int length) {
    for (int i = 0; i < length; i++) {
        for (int j = 0; j < length - i - 1; j++) {
            if (arr[j] > arr[j + 1]) {
                int temp = arr[j];
                arr[j] = arr[j + 1];
                arr[j + 1] = temp;
            }
        }
    }
}

int main() {
    int arr[] = {64, 34, 25, 12, 22, 11, 90};
    int length = sizeof(arr) / sizeof(arr[0]);

    bubbleSort(arr, length);

    cout << "Sorted array: \n";
    for (int i = 0; i < length; i++)
        cout << arr[i] << " ";
    cout << endl;

    return 0;
}
```

