/* Function to find the maximum element in the array */
int findMaxElement(int array[], int size){
    // Initialize maximum element as first element
    int max = array[0];

    // Traverse through the array and compare each element with maximum
    for (int i=1; i < size; i++)
       if (array[i] > max)
           max = array[i];

    // Return the maximum element
    return max;
}


int main(void) {

    int array[] = {8, 3, 5, 9, 3, 1, 5};
    int size = sizeof(array)/sizeof(array[0]);
    int maximum_element = findMaxElement(array, size);

    printf("Maximum element in the array is: %d", maximum_element);

    return 0;
}
